#include <stdio.h>
#include <string.h>

int main() {
    char a[205], b[205], out[205];
    scanf("%s", a);
    scanf("%s", b);

    int n = strlen(a);

    for (int i = 0; i < n; i++) {
        if (a[i] == b[i]) {
            out[i] = '=';
        } else if (((a[i] - 'A' + 1) % 26) == (b[i] - 'A')) {
            out[i] = '+';
        } else if (((a[i] - 'A' + 25) % 26) == (b[i] - 'A')) {
            out[i] = '-';
        } else {
            out[i] = '?';
        }
    }

    out[n] = '\0';
    printf("%s\n", out);

    return 0;
}
